import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p23_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor softmax_rowwise_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("softmax_rowwise_cuda", &softmax_rowwise_cuda, "Row-wise softmax (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

#define WARP_SIZE 32
#define FULL_MASK 0xffffffff

__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1)
        val = fmaxf(val, __shfl_down_sync(FULL_MASK, val, offset));
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1)
        val += __shfl_down_sync(FULL_MASK, val, offset);
    return val;
}

__global__ void softmax_rowwise_kernel(const float* __restrict__ input,
                                        float* __restrict__ output,
                                        int rows, int cols) {
    extern __shared__ float smem[];
    int row = blockIdx.x;
    if (row >= rows) return;

    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int nwarps = nthreads / WARP_SIZE;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;

    const float* row_in = input + (long long)row * cols;
    float* row_out = output + (long long)row * cols;

    // Use float4 vectorized loads when possible
    int cols4 = cols / 4;
    int cols_rem = cols % 4;
    const float4* row_in4 = reinterpret_cast<const float4*>(row_in);

    // Pass 1: compute row max
    float local_max = -FLT_MAX;
    for (int i = tid; i < cols4; i += nthreads) {
        float4 v = __ldg(row_in4 + i);
        local_max = fmaxf(local_max, fmaxf(fmaxf(v.x, v.y), fmaxf(v.z, v.w)));
    }
    // Handle remainder
    int base = cols4 * 4;
    for (int i = base + tid; i < cols; i += nthreads) {
        local_max = fmaxf(local_max, __ldg(row_in + i));
    }

    // Warp reduce max
    local_max = warp_reduce_max(local_max);
    if (lane_id == 0) smem[warp_id] = local_max;
    __syncthreads();

    // Block reduce max
    if (tid < nwarps) {
        float val = smem[tid];
        val = warp_reduce_max(val);
        if (tid == 0) smem[0] = val;
    }
    __syncthreads();
    float row_max = smem[0];

    // Pass 2: compute sum of exp(x - max)
    float local_sum = 0.0f;
    for (int i = tid; i < cols4; i += nthreads) {
        float4 v = __ldg(row_in4 + i);
        local_sum += expf(v.x - row_max) + expf(v.y - row_max) + expf(v.z - row_max) + expf(v.w - row_max);
    }
    for (int i = base + tid; i < cols; i += nthreads) {
        local_sum += expf(__ldg(row_in + i) - row_max);
    }

    // Warp reduce sum
    local_sum = warp_reduce_sum(local_sum);
    if (lane_id == 0) smem[warp_id] = local_sum;
    __syncthreads();

    // Block reduce sum
    if (tid < nwarps) {
        float val = smem[tid];
        val = warp_reduce_sum(val);
        if (tid == 0) smem[0] = val;
    }
    __syncthreads();
    float row_sum = smem[0];
    float inv_sum = 1.0f / row_sum;

    // Pass 3: write normalized output
    float4* row_out4 = reinterpret_cast<float4*>(row_out);
    for (int i = tid; i < cols4; i += nthreads) {
        float4 v = __ldg(row_in4 + i);
        float4 out;
        out.x = expf(v.x - row_max) * inv_sum;
        out.y = expf(v.y - row_max) * inv_sum;
        out.z = expf(v.z - row_max) * inv_sum;
        out.w = expf(v.w - row_max) * inv_sum;
        row_out4[i] = out;
    }
    for (int i = base + tid; i < cols; i += nthreads) {
        row_out[i] = expf(__ldg(row_in + i) - row_max) * inv_sum;
    }
}

torch::Tensor softmax_rowwise_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat, "Input must be float32");
    TORCH_CHECK(x.dim() == 2, "Input must be 2D");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");

    int rows = x.size(0);
    int cols = x.size(1);
    auto output = torch::empty_like(x);

    int threads = 256;
    int nwarps = threads / WARP_SIZE;
    int smem_size = nwarps * sizeof(float);

    softmax_rowwise_kernel<<<rows, threads, smem_size>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        rows, cols
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a Softmax activation.
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Applies Softmax activation to the input tensor.

                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, num_features).

                Returns:
                    torch.Tensor: Output tensor with Softmax applied, same shape as input.
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if x.is_cuda and x.dtype == torch.float32 and x.dim() == 2 and x.is_contiguous():
            return _stark_get_extension().softmax_rowwise_cuda(x)
        return torch.softmax(x, dim=1)
        # <<<END_IMPROVE>>>

