CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor softmax_rowwise_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("softmax_rowwise_cuda", &softmax_rowwise_cuda, "Row-wise online softmax (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

#define WARP_SIZE 32
#define FULL_MASK 0xffffffff

__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1)
        val = fmaxf(val, __shfl_down_sync(FULL_MASK, val, offset));
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1)
        val += __shfl_down_sync(FULL_MASK, val, offset);
    return val;
}

// Online softmax kernel: single pass to compute (max, sum) simultaneously
// then one write pass. Reduces DRAM reads from 2x to 1x row data.
__global__ void softmax_online_kernel(const float* __restrict__ input,
                                       float* __restrict__ output,
                                       int rows, int cols) {
    extern __shared__ float smem[];
    // smem layout: [0..nwarps-1] for max, [nwarps..2*nwarps-1] for sum
    int row = blockIdx.x;
    if (row >= rows) return;

    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int nwarps = nthreads / WARP_SIZE;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;

    const float* row_in = input + (long long)row * cols;
    float* row_out = output + (long long)row * cols;

    int cols4 = cols / 4;
    int base = cols4 * 4;
    const float4* row_in4 = reinterpret_cast<const float4*>(row_in);

    // Online pass: compute local max and sum simultaneously
    float local_max = -FLT_MAX;
    float local_sum = 0.0f;

    for (int i = tid; i < cols4; i += nthreads) {
        float4 v = __ldg(row_in4 + i);
        // Update running max and sum for each element
        float m0 = fmaxf(local_max, v.x);
        local_sum = local_sum * expf(local_max - m0) + expf(v.x - m0);
        local_max = m0;

        float m1 = fmaxf(local_max, v.y);
        local_sum = local_sum * expf(local_max - m1) + expf(v.y - m1);
        local_max = m1;

        float m2 = fmaxf(local_max, v.z);
        local_sum = local_sum * expf(local_max - m2) + expf(v.z - m2);
        local_max = m2;

        float m3 = fmaxf(local_max, v.w);
        local_sum = local_sum * expf(local_max - m3) + expf(v.w - m3);
        local_max = m3;
    }
    for (int i = base + tid; i < cols; i += nthreads) {
        float xi = __ldg(row_in + i);
        float m = fmaxf(local_max, xi);
        local_sum = local_sum * expf(local_max - m) + expf(xi - m);
        local_max = m;
    }

    // Warp-level reduction: merge (max, sum) pairs
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
        float other_max = __shfl_down_sync(FULL_MASK, local_max, offset);
        float other_sum = __shfl_down_sync(FULL_MASK, local_sum, offset);
        if (other_max > local_max) {
            local_sum = local_sum * expf(local_max - other_max) + other_sum;
            local_max = other_max;
        } else {
            local_sum = local_sum + other_sum * expf(other_max - local_max);
        }
    }

    if (lane_id == 0) {
        smem[warp_id] = local_max;
        smem[nwarps + warp_id] = local_sum;
    }
    __syncthreads();

    // Block-level reduction
    if (tid < nwarps) {
        float bmax = smem[tid];
        float bsum = smem[nwarps + tid];
        for (int offset = nwarps / 2; offset > 0; offset >>= 1) {
            float other_max = __shfl_down_sync(FULL_MASK, bmax, offset);
            float other_sum = __shfl_down_sync(FULL_MASK, bsum, offset);
            if (other_max > bmax) {
                bsum = bsum * expf(bmax - other_max) + other_sum;
                bmax = other_max;
            } else {
                bsum = bsum + other_sum * expf(other_max - bmax);
            }
        }
        if (tid == 0) {
            smem[0] = bmax;
            smem[1] = bsum;
        }
    }
    __syncthreads();

    float row_max = smem[0];
    float inv_sum = 1.0f / smem[1];

    // Write pass
    float4* row_out4 = reinterpret_cast<float4*>(row_out);
    for (int i = tid; i < cols4; i += nthreads) {
        float4 v = __ldg(row_in4 + i);
        float4 out;
        out.x = expf(v.x - row_max) * inv_sum;
        out.y = expf(v.y - row_max) * inv_sum;
        out.z = expf(v.z - row_max) * inv_sum;
        out.w = expf(v.w - row_max) * inv_sum;
        row_out4[i] = out;
    }
    for (int i = base + tid; i < cols; i += nthreads) {
        row_out[i] = expf(__ldg(row_in + i) - row_max) * inv_sum;
    }
}

torch::Tensor softmax_rowwise_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat, "Input must be float32");
    TORCH_CHECK(x.dim() == 2, "Input must be 2D");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");

    int rows = x.size(0);
    int cols = x.size(1);
    auto output = torch::empty_like(x);

    int threads = 512;
    int nwarps = threads / WARP_SIZE;
    // smem: nwarps floats for max + nwarps floats for sum, plus 2 for final result
    int smem_size = (2 * nwarps + 2) * sizeof(float);

    softmax_online_kernel<<<rows, threads, smem_size>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        rows, cols
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a Softmax activation.
        """
