// ---- Split-row hierarchical softmax for very wide rows ----
// Kernel 1: each block processes a contiguous chunk of one row,
// writes partial (max, sum) to partials[row * blocks_per_row + chunk_id].
struct PartialStat { float max_val; float sum_val; };

__global__ void softmax_partial_stats(
        const float* __restrict__ input,
        PartialStat* __restrict__ partials,
        int rows, int cols, int blocks_per_row) {

    __shared__ float smem[2 * NWARPS];

    int block_in_row = blockIdx.x % blocks_per_row;
    int row = blockIdx.x / blocks_per_row;
    if (row >= rows) return;

    int tid = threadIdx.x;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;

    // Each block owns a contiguous chunk of the row
    int chunk_size = (cols + blocks_per_row - 1) / blocks_per_row;
    // Align chunk_size to multiple of 4 for float4 safety
    chunk_size = ((chunk_size + 3) / 4) * 4;
    int col_start = block_in_row * chunk_size;
    int col_end = min(col_start + chunk_size, cols);

    const float* row_in = input + (long long)row * cols;

    float lm0 = -FLT_MAX, ls0 = 0.0f;
    float lm1 = -FLT_MAX, ls1 = 0.0f;

    // Use float4 loads where possible
    int local_cols = col_end - col_start;
    int local_cols4 = local_cols / 4;
    const float4* row_in4 = reinterpret_cast<const float4*>(row_in + col_start);

    int stride2 = THREADS * 2;
    int i = tid;
    for (; i + THREADS < local_cols4; i += stride2) {
        float4 v0 = __ldg(row_in4 + i);
        float4 v1 = __ldg(row_in4 + i + THREADS);
        float nm;
        nm = fmaxf(lm0, v0.x); ls0 = ls0 * expf(lm0 - nm) + expf(v0.x - nm); lm0 = nm;
        nm = fmaxf(lm0, v0.y); ls0 = ls0 * expf(lm0 - nm) + expf(v0.y - nm); lm0 = nm;
        nm = fmaxf(lm0, v0.z); ls0 = ls0 * expf(lm0 - nm) + expf(v0.z - nm); lm0 = nm;
        nm = fmaxf(lm0, v0.w); ls0 = ls0 * expf(lm0 - nm) + expf(v0.w - nm); lm0 = nm;
        nm = fmaxf(lm1, v1.x); ls1 = ls1 * expf(lm1 - nm) + expf(v1.x - nm); lm1 = nm;
        nm = fmaxf(lm1, v1.y); ls1 = ls1 * expf(lm1 - nm) + expf(v1.y - nm); lm1 = nm;
        nm = fmaxf(lm1, v1.z); ls1 = ls1 * expf(lm1 - nm) + expf(v1.z - nm); lm1 = nm;
        nm = fmaxf(lm1, v1.w); ls1 = ls1 * expf(lm1 - nm) + expf(v1.w - nm); lm1 = nm;
    }
    if (i < local_cols4) {
        float4 v0 = __ldg(row_in4 + i);
        float nm;
        nm = fmaxf(lm0, v0.x); ls0 = ls0 * expf(lm0 - nm) + expf(v0.x - nm); lm0 = nm;
        nm = fmaxf(lm0, v0.y); ls0 = ls0 * expf(lm0 - nm) + expf(v0.y - nm); lm0 = nm;
        nm = fmaxf(lm0, v0.z); ls0 = ls0 * expf(lm0 - nm) + expf(v0.z - nm); lm0 = nm;
        nm = fmaxf(lm0, v0.w); ls0 = ls0 * expf(lm0 - nm) + expf(v0.w - nm); lm0 = nm;
    }
    merge_pair(lm0, ls0, lm1, ls1);

    // Scalar tail
    int base = col_start + local_cols4 * 4;
    for (int j = base + tid; j < col_end; j += THREADS) {
        float x = __ldg(row_in + j);
        float nm = fmaxf(lm0, x);
        ls0 = ls0 * expf(lm0 - nm) + expf(x - nm);
        lm0 = nm;
    }

    // Warp reduction
    #pragma unroll
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
        float om = __shfl_down_sync(FULL_MASK, lm0, offset);
        float os = __shfl_down_sync(FULL_MASK, ls0, offset);
        merge_pair(lm0, ls0, om, os);
    }
    if (lane_id == 0) { smem[warp_id] = lm0; smem[NWARPS + warp_id] = ls0; }
    __syncthreads();

    if (warp_id == 0) {
        float w_max = (lane_id < NWARPS) ? smem[lane_id] : -FLT_MAX;
        float w_sum = (lane_id < NWARPS) ? smem[NWARPS + lane_id] : 0.0f;
        #pragma unroll
        for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
            float om = __shfl_down_sync(FULL_MASK, w_max, offset);
            float os = __shfl_down_sync(FULL_MASK, w_sum, offset);
            merge_pair(w_max, w_sum, om, os);
        }
        if (lane_id == 0) {
            partials[row * blocks_per_row + block_in_row].max_val = w_max;
            partials[row * blocks_per_row + block_in_row].sum_val = w_sum;
        }
    }
}

// Kernel 2: one block per row; reduce partials, then normalize output.
__global__ void softmax_finalize(
        const float* __restrict__ input,
        float* __restrict__ output,
        const PartialStat* __restrict__ partials,
        int rows, int cols, int blocks_per_row) {

    int row = blockIdx.x;
    if (row >= rows) return;

    int tid = threadIdx.x;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;

    // Reduce partials for this row (blocks_per_row <= 32 so fits in one warp)
    float global_max = -FLT_MAX, global_sum = 0.0f;
    if (warp_id == 0) {
        if (lane_id < blocks_per_row) {
            global_max = partials[row * blocks_per_row + lane_id].max_val;
            global_sum = partials[row * blocks_per_row + lane_id].sum_val;
        }
        #pragma unroll
        for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
            float om = __shfl_down_sync(FULL_MASK, global_max, offset);
            float os = __shfl_down_sync(FULL_MASK, global_sum, offset);
            merge_pair(global_max, global_sum, om, os);
        }
    }
    // Broadcast to all threads via shared memory
    __shared__ float smem_gs[2];
    if (tid == 0) { smem_gs[0] = global_max; smem_gs[1] = global_sum; }
    __syncthreads();
    global_max = smem_gs[0];
    global_sum = smem_gs[1];
    float inv_sum = 1.0f / global_sum;

    const float* row_in = input + (long long)row * cols;
    float* row_out = output + (long long)row * cols;

    int cols4 = cols / 4;
    const float4* row_in4 = reinterpret_cast<const float4*>(row_in);
    float4* row_out4 = reinterpret_cast<float4*>(row_out);

    int stride2 = THREADS * 2;
    int i = tid;
    for (; i + THREADS < cols4; i += stride2) {
        float4 v0 = __ldg(row_in4 + i);
        float4 v1 = __ldg(row_in4 + i + THREADS);
        float4 out0, out1;
        out0.x = expf(v0.x - global_max) * inv_sum; out0.y = expf(v0.y - global_max) * inv_sum;
        out0.z = expf(v0.z - global_max) * inv_sum; out0.w = expf(v0.w - global_max) * inv_sum;
        out1.x = expf(v1.x - global_max) * inv_sum; out1.y = expf(v1.y - global_max) * inv_sum;
        out1.z = expf(v1.z - global_max) * inv_sum; out1.w = expf(v1.w - global_max) * inv_sum;
        row_out4[i] = out0;
        row_out4[i + THREADS] = out1;
    }
    if (i < cols4) {
        float4 v0 = __ldg(row_in4 + i);
        float4 out0;
        out0.x = expf(v0.x - global_max) * inv_sum; out0.y = expf(v0.y - global_max) * inv_sum;
        out0.z = expf(v0.z - global_max) * inv_sum; out0.w = expf(v0.w - global_max) * inv_sum;
        row_out4[i] = out0;
    }
    int base = cols4 * 4;
    for (int j = base + tid; j < cols; j += THREADS) {
        row_out[j] = expf(__ldg(row_in + j) - global_max) * inv_sum;
    }
}

torch::Tensor softmax_rowwise_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(x.dim() == 2, "Input must be 2D");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");

    int rows = x.size(0);
    int cols = x.size(1);

    auto output = torch::empty_like(x);

    constexpr int threads = THREADS;
    constexpr int nwarps = NWARPS;
    size_t smem_size = 2 * nwarps * sizeof(float);

    // Use split-row path for very wide rows (cols >= 131072)
    // blocks_per_row must be <= 32 (fits in one warp for final reduction)
    if (cols >= 131072 && rows > 0) {
        // Choose blocks_per_row: 8 gives each block ~49152 elements (48 float4 per thread)
        // Keep <= 32 so final reduction fits in one warp
        const int blocks_per_row = 8;

        // Allocate partial stats workspace
        auto partials_tensor = torch::empty(
            {(long long)rows * blocks_per_row * 2},
            torch::TensorOptions().dtype(torch::kFloat32).device(x.device())
        );
        PartialStat* partials_ptr = reinterpret_cast<PartialStat*>(partials_tensor.data_ptr<float>());

        // Kernel 1: compute partial (max, sum) per chunk
        int grid1 = rows * blocks_per_row;
        softmax_partial_stats<<<grid1, threads, smem_size>>>(
            x.data_ptr<float>(),
            partials_ptr,
            rows, cols, blocks_per_row
        );

        // Kernel 2: finalize normalization
        softmax_finalize<<<rows, threads, 0>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            partials_ptr,
            rows, cols, blocks_per_row
        );
    } else {
        softmax_rowwise_kernel<<<rows, threads, smem_size>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            rows, cols
        );
    }

    return output;
}
